package com.termux.app.workspace;
import android.app.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowAlertDialog;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class AgentPermissionPolicyUiTest {
 Activity a;AtomicInteger saved;
 @Before public void setup(){a=Robolectric.buildActivity(Activity.class).setup().get();a.setTheme(com.termux.R.style.Theme_Termux_Black);saved=new AtomicInteger();}
 @After public void close(){AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();if(d!=null)d.dismiss();a.finish();}
 AlertDialog open(WorkspaceStore.Session p){AgentPermissionsUi.show(a,p,null,false,()->true,s->saved.incrementAndGet());return ShadowAlertDialog.getLatestAlertDialog();}
 void click(AlertDialog d,int button){d.getButton(button).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}
 @Test public void cancelAndConflictDoNotSaveButExplicitSavePreservesUntrustedPolicy(){WorkspaceStore.Session p=new WorkspaceStore.Session();p.environment="codex";p.codexAccess="project";p.codexConfirmActions=false;p.codexUntrustedApproval=true;AlertDialog d=open(p);((CheckBox)d.findViewById(android.R.id.content).findViewWithTag("codex-command-confirmations")).setChecked(true);click(d,-2);assertEquals(Boolean.FALSE,p.codexConfirmActions);assertEquals(0,saved.get());d=open(p);((CheckBox)d.getWindow().getDecorView().findViewWithTag("codex-command-confirmations")).setChecked(true);p.codexAccess="read";click(d,-1);assertEquals(0,saved.get());assertTrue(d.isShowing());d.dismiss();d=open(p);((CheckBox)d.getWindow().getDecorView().findViewWithTag("codex-command-confirmations")).setChecked(true);click(d,-1);assertEquals(1,saved.get());assertEquals("untrusted",CodexSessionShell.approval(p));assertEquals("read",p.codexAccess);}
 @Test public void staleRunCannotSaveAndScopeOnlyDoesNotOverwriteLiveMode(){WorkspaceStore.Session p=new WorkspaceStore.Session();p.aiAgent="opencode";p.aiAccess="ask";p.aiProjectOnly=true;AgentPermissionsUi.show(a,p,null,true,()->true,s->saved.incrementAndGet());AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();assertNull(d.getWindow().getDecorView().findViewWithTag("agent-status-launch-permission"));((CheckBox)d.getWindow().getDecorView().findViewWithTag("opencode-project-scope")).setChecked(false);p.aiAccess="read";click(d,-1);assertFalse(p.aiProjectOnly);assertEquals("read",p.aiAccess);assertEquals(1,saved.get());AgentPermissionsUi.show(a,p,null,false,()->false,s->saved.incrementAndGet());d=ShadowAlertDialog.getLatestAlertDialog();click(d,-1);assertEquals(1,saved.get());assertTrue(d.isShowing());}
}
